import{_ as e,c as t,o as i,ag as o}from"./chunks/framework.B-XtCDNB.js";const g=JSON.parse(`{"title":"Valadoc Guide","description":"Valadoc Guide valadoc is a command line tool that generates Vala programming documentation from a library's API (Application Programming Interface). The library's API can be written manually in a...","frontmatter":{"prev":{"text":"8.1. From Swing to GTK+","link":"/guides/vala-for-java-programmers/08-swing-to-gtk/01-from-swing-to-gtk"},"next":{"text":"1. Quick Start","link":"/guides/valadoc-guide/01-00-quick-start"}},"headers":[],"relativePath":"guides/valadoc-guide.md","filePath":"guides/valadoc-guide.md","lastUpdated":1786207193000}`),n={name:"guides/valadoc-guide.md"};function r(l,a,d,c,m,s){return i(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="valadoc-guide" tabindex="-1">Valadoc Guide <a class="header-anchor" href="#valadoc-guide" aria-label="Permalink to &quot;Valadoc Guide&quot;">​</a></h1><p><code>valadoc</code> is a command line tool that generates Vala programming documentation from a library&#39;s API (Application Programming Interface).</p><p>The library&#39;s API can be <a href="./bindings/writing-a-vapi-manually.html">written manually</a> in a VAPI file or in a VAPI file or <a href="./bindings/generating-a-vapi-with-gobject-introspection.html">generated automatically</a> from source files and held in a GIR (GObject Introspection Repository) file. valadoc can generate documentation from both a VAPI file or a GIR file.</p><p>If the library is written in Vala then valadoc can generate the documentation from the library&#39;s Vala source files.</p><ul class="section-toc"><li><a href="valadoc-guide/01-00-quick-start">1. Quick Start</a></li><li><a href="valadoc-guide/02-00-command-line-tool">2. Command Line Tool</a></li><li><a href="valadoc-guide/03-00-documentation-comment-markup">3. Documentation Comment Markup</a></li><li><a href="valadoc-guide/04-00-contributing-to-valadoc">4. Contributing to Valadoc</a></li></ul>',5)])])}cons